effect.shader:
vec4 src(vec2 uv){ return texture2DCv(inputImg.texture, uv); }

void main(){
  vec2 uv = acScreenNorm;
  vec4 srcCol = src(uv);
  vec3 hdr = srcCol.rgb;
  vec3 accum = vec3(floor(level + pow(hdr.r, basePower)));

  float c = float(max(iterations, 1.0));
  vec2 r = acScreenSize * max(radiusScale, 1e-3);
  int samples = int(iterations);

  for(int i=0;i<2048;i++){
    if(i>=samples) break;
    float it = float(i);
    float w = (1.0 - it / c);

    float texL = src(uv + vec2(it / r.x, 0.0)).r;
    float texR = src(uv - vec2(it / r.x, 0.0)).r;
    accum += floor(level + pow(max(texL, texR), float(peakPower))) * w;

    float texU = src(uv + vec2(0.0, it / r.y)).r;
    float texD = src(uv - vec2(0.0, it / r.y)).r;
    accum += floor(level + pow(max(texU, texD), float(peakPower))) * w;

    float ring = smoothstep(0.5, 0.75, length(vec2(it / r.x, it / r.y))) / c;
    accum += pow(ring, 1.0 / max(falloffExp, 1e-3));
  }

  vec3 effectRGB = pow(accum * strength, vec3(1.0 / max(gamma, 1e-6)));
  effectRGB *= tintColor.rgb;

  vec3 luma = vec3(0.299, 0.587, 0.114);
  float lum = dot(srcCol.rgb, luma);
  float gate = smoothstep(bloomThreshold, 1.0, lum);
  vec3 b0 = srcCol.rgb * gate;
  vec2 texel = vec2(bloomRadius) / max(acScreenSize, vec2(1.0));
  vec3 b = b0;
  vec3 s1 = src(uv + texel * vec2( 1.0,  0.0)).rgb; b += s1 * smoothstep(bloomThreshold, 1.0, dot(s1, luma));
  vec3 s2 = src(uv + texel * vec2(-1.0,  0.0)).rgb; b += s2 * smoothstep(bloomThreshold, 1.0, dot(s2, luma));
  vec3 s3 = src(uv + texel * vec2( 0.0,  1.0)).rgb; b += s3 * smoothstep(bloomThreshold, 1.0, dot(s3, luma));
  vec3 s4 = src(uv + texel * vec2( 0.0, -1.0)).rgb; b += s4 * smoothstep(bloomThreshold, 1.0, dot(s4, luma));
  vec3 s5 = src(uv + texel * vec2( 1.0,  1.0)).rgb; b += s5 * smoothstep(bloomThreshold, 1.0, dot(s5, luma));
  vec3 s6 = src(uv + texel * vec2(-1.0,  1.0)).rgb; b += s6 * smoothstep(bloomThreshold, 1.0, dot(s6, luma));
  vec3 s7 = src(uv + texel * vec2( 1.0, -1.0)).rgb; b += s7 * smoothstep(bloomThreshold, 1.0, dot(s7, luma));
  vec3 s8 = src(uv + texel * vec2(-1.0, -1.0)).rgb; b += s8 * smoothstep(bloomThreshold, 1.0, dot(s8, luma));
  b *= (1.0/9.0);
  vec3 bloom = b * bloomStrength;

  int bm = int(blendMode);
  vec3 outRGB;
  if(bm==1){
    outRGB = effectRGB;
  } else if(bm==2){
    outRGB = srcCol.rgb + effectRGB;
  } else if(bm==3){
    outRGB = 1.0 - (1.0 - srcCol.rgb) * (1.0 - effectRGB);
  } else {
    outRGB = mix(effectRGB, srcCol.rgb, srcCol.a);
  }

  outRGB += bloom;

  vec3 mixed = mix(srcCol.rgb, outRGB, clamp(mixAmount, 0.0, 1.0));
  gl_FragColor = vec4(mixed, srcCol.a);
}
